    #[test]
    fn test_06_codegen() {
        let mut db = ProjectDatabase::new();
        db.set_project_root(std::path::Path::new("."));
        {
            let content = include_str!(
                "/Users/greghale/code/baml/baml_language/crates/baml_tests/projects/builtin_io/fs_ops.baml"
            );
            let content = content.replace("\r\n", "\n");
            db.add_file("fs_ops.baml", &content);
        }
        {
            let content = include_str!(
                "/Users/greghale/code/baml/baml_language/crates/baml_tests/projects/builtin_io/net_ops.baml"
            );
            let content = content.replace("\r\n", "\n");
            db.add_file("net_ops.baml", &content);
        }
        {
            let content = include_str!(
                "/Users/greghale/code/baml/baml_language/crates/baml_tests/projects/builtin_io/shell_ops.baml"
            );
            let content = content.replace("\r\n", "\n");
            db.add_file("shell_ops.baml", &content);
        }
        let mut output = String::new();
        let options = baml_compiler2_emit::CompileOptions {
            emit_test_cases: false,
        };
        match baml_compiler2_emit::generate_project_bytecode(&db, &options) {
            Ok(program) => {
                let mut func_names: Vec<_> = program
                    .function_indices
                    .keys()
                    .filter(|name: &&String| {
                        !name.starts_with(BAML_STD_PREFIX) && !name.starts_with("env.")
                    })
                    .collect();
                func_names.sort();
                let functions: Vec<(String, &bex_vm_types::types::Function)> = func_names
                    .iter()
                    .map(|name| {
                        let idx = *program.function_indices.get(*name).unwrap();
                        match program.objects.get(idx) {
                            Some(bex_vm_types::Object::Function(func)) => {
                                ((*name).clone(), func.as_ref())
                            }
                            other => {
                                panic!(
                                    "function_indices entry '{}' (idx={}) is not a Function: {:?}",
                                    name, idx, other.map(std::mem::discriminant)
                                );
                            }
                        }
                    })
                    .collect();
                output = bex_vm::debug::display_program(
                    &functions,
                    bex_vm::debug::BytecodeFormat::Textual,
                );
            }
            Err(err) => {
                writeln!(output, "=== NO CODEGEN DUE TO ERRORS ===").unwrap();
                writeln!(output, "Error: {:?}", err).unwrap();
            }
        }
        with_settings!(
            { snapshot_path => SNAPSHOT_PATH, omit_expression => true }, {
            assert_snapshot!("06_codegen", output); }
        );
    }
    #[test]
    fn test_10_formatter_fs_ops() {
        let content = include_str!(
            "/Users/greghale/code/baml/baml_language/crates/baml_tests/projects/builtin_io/fs_ops.baml"
        );
        let content = content.replace("\r\n", "\n");
        let options = baml_fmt::FormatOptions::default();
        let first = match baml_fmt::format(&content, &options) {
            Ok(formatted) => formatted,
            Err(e) => {
                let output = match e {
                    baml_fmt::FormatterError::ParseErrors(e) => {
                        format!("=== PARSER ERROR ===\n{:?}", e)
                    }
                    baml_fmt::FormatterError::StrongAstError(e) => {
                        let e = e.print_with_file_context("fs_ops.baml", &content);
                        format!("=== STRONG AST ERROR ===\n{}", e)
                    }
                };
                with_settings!(
                    { snapshot_path => SNAPSHOT_PATH, omit_expression => true }, {
                    assert_snapshot!("10_formatter__fs_ops", output); }
                );
                return;
            }
        };
        with_settings!(
            { snapshot_path => SNAPSHOT_PATH, omit_expression => true }, {
            assert_snapshot!("10_formatter__fs_ops", first); }
        );
        let second = match baml_fmt::format(&first, &options) {
            Ok(formatted) => formatted,
            Err(e) => {
                panic!(
                    "Formatter succeeded on the original input ({}) but failed on its own output:\n{}",
                    "fs_ops.baml", e
                );
            }
        };
        if first != second {
            std::fs::write(
                    format!("{}/{}.new", SNAPSHOT_PATH, "fs_ops.baml"),
                    second.as_bytes(),
                )
                .unwrap();
            panic!(
                "Formatter is not idempotent for {}.\n\
                    Second pass output written to {}/{}.new",
                "fs_ops.baml", SNAPSHOT_PATH, "fs_ops.baml"
            );
        }
    }
