    fn test_10_formatter_precedence() {
        let content = include_str!(
            "/Users/greghale/code/baml/baml_language/crates/baml_tests/projects/parser_expressions/precedence.baml"
        );
        let content = content.replace("\r\n", "\n");
        let options = baml_fmt::FormatOptions::default();
        let first = match baml_fmt::format(&content, &options) {
            Ok(formatted) => formatted,
            Err(e) => {
                let output = match e {
                    baml_fmt::FormatterError::ParseErrors(e) => {
                        format!("=== PARSER ERROR ===\n{:?}", e)
                    }
                    baml_fmt::FormatterError::StrongAstError(e) => {
                        let e = e.print_with_file_context("precedence.baml", &content);
                        format!("=== STRONG AST ERROR ===\n{}", e)
                    }
                };
                with_settings!(
                    { snapshot_path => SNAPSHOT_PATH, omit_expression => true }, {
                    assert_snapshot!("10_formatter__precedence", output); }
                );
                return;
            }
        };
        with_settings!(
            { snapshot_path => SNAPSHOT_PATH, omit_expression => true }, {
            assert_snapshot!("10_formatter__precedence", first); }
        );
        let second = match baml_fmt::format(&first, &options) {
            Ok(formatted) => formatted,
            Err(e) => {
                panic!(
                    "Formatter succeeded on the original input ({}) but failed on its own output:\n{}",
                    "precedence.baml", e
                );
            }
        };
        if first != second {
            std::fs::write(
                    format!("{}/{}.new", SNAPSHOT_PATH, "precedence.baml"),
                    second.as_bytes(),
                )
                .unwrap();
            panic!(
                "Formatter is not idempotent for {}.\n\
                    Second pass output written to {}/{}.new",
                "precedence.baml", SNAPSHOT_PATH, "precedence.baml"
            );
        }
    }
